<script setup>import{Head,useForm,router}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';defineProps({users:Object});const f=useForm({name:'',email:'',role:'monitor',password:'',password_confirmation:''});</script><template><Head title="Users"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">Users</h1><p class="text-xs text-slate-500">Administrator and read-only monitoring access</p></div></template><form @submit.prevent="f.post(route('users.store'),{onSuccess:()=>f.reset()})" class="mb-5 grid gap-3 rounded-xl border border-slate-800 bg-slate-900 p-4 md:grid-cols-5"><input v-model="f.name" required placeholder="Name" class="field"><input v-model="f.email" required type="email" placeholder="Email" class="field"><select v-model="f.role" class="field"><option value="monitor">Monitor</option><option value="admin">Admin</option></select><input v-model="f.password" required type="password" placeholder="Password (12+)" class="field"><input v-model="f.password_confirmation" required type="password" placeholder="Confirm password" class="field"><button class="rounded-lg bg-emerald-500 py-2 font-bold text-slate-950 md:col-start-5">Create user</button></form><div class="rounded-xl border border-slate-800 bg-slate-900"><div v-for="u in users.data" class="flex items-center justify-between border-b border-slate-800 p-4"><div><b class="text-white">{{u.name}}</b><div class="text-xs text-slate-500">{{u.email}}</div></div><select :value="u.role" @change="router.put(route('users.update',u.id),{role:$event.target.value})" class="rounded border-slate-700 bg-slate-950 text-sm"><option value="monitor">Monitor</option><option value="admin">Admin</option></select></div></div></AuthenticatedLayout></template>
